42	int k_sem_take(struct k_sem *sem, k_timeout_t timeout)
43	{
44		int ret;
45		uint32_t ms;
46		struct timespec abstime;
47	
48		if (K_TIMEOUT_EQ(timeout, K_FOREVER))
49			return nxsem_wait_uninterruptible(&sem->sem);
50		else if (K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
51			ret = nxsem_trywait(&sem->sem);
52			if (ret) {
53				return -EBUSY;
54			}
55	
56			return 0;
57		}
58	
59		clock_gettime(CLOCK_REALTIME, &abstime);
60	
61		ms = k_ticks_to_ms_ceil32(timeout.ticks);
62	
63		abstime.tv_sec += ms / MSEC_PER_SEC;
64		abstime.tv_nsec += (ms % MSEC_PER_SEC) * NSEC_PER_MSEC;
65		if (abstime.tv_nsec >= NSEC_PER_SEC) {
66			abstime.tv_sec += 1;
67			abstime.tv_nsec -= NSEC_PER_SEC;
68		}
69	
70		ret = nxsem_timedwait_uninterruptible(&sem->sem, &abstime);
71		if (ret) {
72			return -EAGAIN;
73		}
74	
75		return 0;
76	}
