742:int nxsig_dispatch(pid_t pid, FAR siginfo_t *info, bool thread)
743:{
744:#ifdef HAVE_GROUP_MEMBERS
745:  FAR struct tcb_s *stcb = NULL;
746:  FAR struct task_group_s *group = NULL;
747:  int ret = -ESRCH;
748:
749:  /* Get the TCB associated with the pid */
750:
751:  if (pid == 0)
752:    {
753:      stcb = this_task();
754:    }
755:  else
756:    {
757:      stcb = nxsched_get_tcb(pid);
758:    }
759:
760:  if (stcb != NULL)
761:    {
762:      /* The task/thread associated with this PID is still active.
763:       * Get its task group.
764:       */
765:
766:      group = stcb->group;
767:    }
768:
769:  /* Did we locate the group? */
770:
771:  if (group && !(atomic_read(&group->tg_flags) & GROUP_FLAG_EXITING))
772:    {
773:      if (thread)
774:        {
775:          /* Before the notification, we should validate the tid and
776:           * and make sure that the notified thread is in same process
777:           * with the current thread.
778:           */
779:
780:          if (group == this_task()->group)
781:            {
782:              ret = nxsig_tcbdispatch(stcb, info);
783:            }
784:        }
785:      else
786:        {
787:          /* Yes.. call group_signal() to send the signal to the correct
788:           * group member.
789:           */
790:
791:          ret = group_signal(group, info);
792:        }
793:    }
794:
795:  if (stcb != NULL)
796:    {
797:      nxsched_put_tcb(stcb);
798:    }
