36	{
37		uint32_t ms;
38		struct timespec abstime;
39	
40		if (K_TIMEOUT_EQ(timeout, K_FOREVER))
41			return pthread_mutex_lock(&mutex->mutex);
42		else if (K_TIMEOUT_EQ(timeout, K_NO_WAIT))
43			return pthread_mutex_trylock(&mutex->mutex);
44	
45		clock_gettime(CLOCK_REALTIME, &abstime);
46	
47		ms = k_ticks_to_ms_ceil32(timeout.ticks);
48	
