50		abstime.tv_nsec += (ms % MSEC_PER_SEC) * NSEC_PER_MSEC;
51		if (abstime.tv_nsec >= NSEC_PER_SEC) {
52			abstime.tv_sec += 1;
53			abstime.tv_nsec -= NSEC_PER_SEC;
54		}
55	
56		return pthread_mutex_timedlock(&mutex->mutex, &abstime);
