{
	struct k_poll_event event;
	...
	k_poll_event_init(&event, K_POLL_TYPE_DATA_AVAILABLE,
			  K_POLL_MODE_NOTIFY_ONLY, queue);

	event.state = K_POLL_STATE_NOT_READY;
